  // ── 阵营说明 ──
  '钢铁与工厂的工业强国，信奉火力与装甲。': 'An industrial power of steel and factories that puts its faith in firepower and armor.',  // FACTIONS.1.culture
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Tracked vehicles get Defense +5%; repair cost for ground units at Factories −20%.',  // FACTIONS.1.trait
  '海洋与天空的联邦，重视技术与后勤。': 'A federation of sea and sky that prizes technology and logistics.',  // FACTIONS.2.culture
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Air units and ships get Vision +1; repair cost for air units at Airports and ships at Ports −20%.',  // FACTIONS.2.trait
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'A guerrilla people of forested mountains and snowfields, masters of terrain and concealment.',  // FACTIONS.3.culture
  '步兵类单位造价 −5%；位于森林、山地的步兵类单位防御 +10%；中型坦克、重型坦克、火箭炮造价 +5%。': 'Foot soldiers cost −5%; foot soldiers on Forest and Mountain get Defense +10%; Medium Tank, Heavy Tank and Rocket Launcher cost +5%.',  // FACTIONS.3.trait
  '商路与黄金的城邦联盟，凭借财力与城墙作战。': 'A league of city-states built on trade routes and gold that fights with wealth and walls.',  // FACTIONS.4.culture
  '城市收入 +10%；位于建筑的单位防御 +5%，位于平原的单位防御 −5%。': 'City income +10%; units on buildings get Defense +5%, and units on Plain get Defense −5%.',  // FACTIONS.4.trait

