  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Low cost. Can capture buildings and enter Mountain and River.',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Infantry armed with bazookas. Can capture buildings. High damage to tanks. Movement cost on Mountain and River is 1.',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Ranged infantry with Range 2–4. Strong against foot soldiers; can also attack light vehicles and helicopters. Range +1 on Mountain. Cannot attack after moving.',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Range 1–2. Can still attack after moving. When attacking, the target\'s terrain defense is halved. Strong against foot soldiers on buildings, Forest and Mountain. Is not counterattacked when attacking a target 2 spaces away. Range +1 on Mountain. Cannot attack air units or ships. Cannot capture.',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Range 1. When attacking, ignores the target\'s terrain defense. Strong against foot soldiers on buildings and Mountain. With Fog of War on, reveals hidden units in Forest and Ruins on the 8 surrounding spaces. Weak against ranged units and vehicles. Cannot attack air units or ships. Cannot capture.',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Unarmed. Your adjacent foot soldiers restore 2 HP per turn (at no cost). The effects of multiple Medics do not stack.',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Infantry on motorcycles. Can capture buildings. High Movement, suited to capturing distant buildings. Cannot enter Mountain.',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'Highest Movement of all ground units. Strong against foot soldiers and unescorted artillery. Weak against tanks.',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': 'Mainstay ground unit. Fairly low cost, with balanced Attack and Defense.',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': 'Higher Attack and Defense than the Light Tank, at a moderate cost.',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'Highest Attack and Defense of all ground units. High cost, low Movement.',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Range 2–3. Can attack ships. Cannot attack after moving. Cannot attack adjacent enemy units.',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Range 3–5, longer than Artillery. Strong against heavy vehicles. Cannot attack after moving.',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Range 1. Strong against air units; also deals fairly high damage to foot soldiers.',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Unarmed. Your adjacent vehicles, air units and ships restore 1 HP per turn (at no cost).',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'Movement is unaffected by terrain. Strong against ground units. Weak against Anti-Air.',  // UNITS.cop.desc
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Can attack ground units and helicopters. Lower cost than the Bomber.',  // UNITS.atk.desc
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Very high damage to ground units and ships. Cannot attack air units.',  // UNITS.bmb.desc
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Small, low-cost ship. Can attack ground units on the shore. Strong against Landers.',  // UNITS.gbt.desc
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Anti-air and anti-submarine ship. Strong against Submarines and air units.',  // UNITS.dst.desc
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Range 2–6. Can attack ground units and ships, with fairly high damage. Cannot attack after moving.',  // UNITS.bsh.desc
  '无武装。可搭载 2 个陆上单位，靠岸后卸载。': 'Unarmed. Can load 2 ground units and unload them at the shore.',  // UNITS.lnd.desc

