  '每回合提供 100 资金。可生产航空单位。停留的己方航空单位与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Provides 100 Funds per turn. Can build air units. Your air units and foot soldiers stationed here restore 2 HP per turn (costs Funds).',  // TERRAIN.airport.note
  '每回合提供 100 资金。可生产舰船。停留的己方舰船与步兵类单位每回合恢复 2 HP（需支付资金）。': 'Provides 100 Funds per turn. Can build ships. Your ships and foot soldiers stationed here restore 2 HP per turn (costs Funds).',  // TERRAIN.port.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Your foot soldiers stationed here restore 2 HP per turn (costs Funds). Your units within 5 spaces of your Radar Tower get Attack +10%. The effects of multiple Radar Towers do not stack.',  // TERRAIN.tower.note
  '停留的己方步兵类单位每回合恢复 4 HP，相邻四格内的己方步兵类单位每回合恢复 2 HP（需支付资金）。': 'Your foot soldiers stationed here restore 4 HP per turn, and your adjacent foot soldiers restore 2 HP per turn (costs Funds).',  // TERRAIN.hospital.note
  '停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。位于己方或中立碉堡的单位受到的反击伤害减半，其中远程单位（含投弹手）射程 +1。': 'Your foot soldiers stationed here restore 2 HP per turn (costs Funds). Units on your Bunker or a neutral Bunker take half counterattack damage, and ranged units among them (including Grenadiers) get Range +1.',  // TERRAIN.fort.note
  '可占领建筑的兵种（步兵、破甲兵、摩托兵）进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP（最低保留 1 HP）。': 'A unit type that can capture buildings (Infantry, Bazooka Trooper, Biker) can enter and launch once: choose a center space, and all units within 2 spaces each lose 3 HP (at least 1 HP remains).',  // TERRAIN.silo.note

