  '抛射：移动后仍可攻击。': 'Lobbed fire: can still attack after moving.',  // codex.js:169
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': 'Cannot attack adjacent enemy units, and cannot counterattack when attacked by an adjacent enemy unit.',  // codex.js:170
  '攻击时无视目标的地形防御。': 'When attacking, ignores the target\'s terrain defense.',  // codex.js:171
  '所有阵营均可研究。': 'Available to all factions.',  // codex.js:196
  '通用与阵营': 'Common and Faction',  // codex.js:204
  '克制表　行为攻击方，列为防守方，数值为基础伤害（%）': 'Matchups: rows attack, columns defend; values are base damage (%)',  // codex.js:211
  '攻 ＼ 守': 'Atk \\ Def',  // codex.js:211
  '胜负': 'Win / Lose',  // codex.js:235
  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'With a Day limit set, when it is reached the teams are compared first by number of income buildings, then by total unit cost.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'Each building has 20 capture points; each capture action subtracts the unit\'s current HP. A unit at full HP needs 2 turns to complete a capture.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'If the capturing unit leaves or is destroyed, capture points return to 20. Allied buildings cannot be captured.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'The HP of the two units is added together; any HP above 10 is refunded as Funds based on cost.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': 'A unit attacked by a non-adjacent enemy unit cannot counterattack.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Your units within 5 spaces of your Radar Tower get Attack +10%. The effects of multiple Radar Towers do not stack.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'With Fog of War on, your Radar Tower can see 5 spaces around it.',  // codex.js:276
  '不提供收入。': 'Provides no income.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'A unit type that can capture buildings can enter and launch once: choose a center space, and all units within 2 spaces each lose 3 HP.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'Each enemy unit destroyed gives +1 star, up to 3 stars.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': 'Each 1 star gives Attack +5% and Defense +5%.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'After a transport moves, choose “Unload” to place a carried unit on an adjacent empty space it can enter. An unloaded unit cannot act again this turn.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Once the Power Meter is full, you can activate the CO Power on your turn; its effect lasts until the start of your next turn.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'A CO Power only affects your own faction. For each CO\'s Power, see the “CO” page.',  // codex.js:284
  '特长与阵营特性': 'Specialties and Faction Traits',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': 'Each CO has one Specialty, in effect from the start of the game.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'A CO also has the Trait of the faction they belong to, regardless of the army color in this game.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Sources of Research Points: research funding, your Research Labs, and each faction\'s research method (see the “Faction” page).',  // codex.js:294
  '多阵营与结盟': 'Factions and Alliances',  // codex.js:308
  '同队阵营不可互相攻击，不可占领友方的建筑。可穿过友方单位所在的格子，但不可停留。': 'Factions on the same team cannot attack each other or capture allied buildings. Units can pass through spaces occupied by allied units, but cannot stop there.',  // codex.js:310
