  '只能在道路、桥梁和建筑上移动。射程 1–3，移动后只能攻击相邻目标。可搭载 2 个徒步的步兵类单位（摩托兵除外）。攻击与防御介于中型坦克和重型坦克之间。': 'Can only move on Road, Bridge and building spaces. Range 1–3; after moving, can only attack adjacent targets. Can load 2 foot soldiers that move on foot (Bikers excluded). Attack and Defense fall between the Medium Tank and the Heavy Tank.',
