  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': 'A ground unit that ends its move on this space picks it up: gain 1–3 Meteor Shards (set at random for each pile at the start of the match), and this space becomes a Shard Pit (same as Wasteland). Movement cost for wheeled vehicles is 3.',
