  '{a} 必须是对象': '{a} must be an object',
  '地图「{a}」的 rows / half 必须是等宽的字符串数组': 'rows / half of map “{a}” must be an array of strings of equal width',
  '指挥官「{a}」的 faction 必须是 1–5': 'faction of CO “{a}” must be 1–5',
  '指挥官「{a}」的 mods 必须是数组': 'mods of CO “{a}” must be an array',
  '指挥官「{a}」的 mods 里有无法识别的字段 {b}': 'mods of CO “{a}” has an unrecognized field {b}',
